<script>
import Icon from './Icon.svelte';
import {onMount} from 'svelte';import UnsavedChanges from './UnsavedChanges.svelte';import {beforeNavigate,goto} from '$app/navigation';
import FaultSettings from './FaultSettings.svelte';
import {api} from './api.js';import RampEditor from './RampEditor.svelte';import FlowMix from './FlowMix.svelte';import {profileSummary} from './flow-catalog.mjs';import {loadShape} from './load-shape.mjs';
export let profile;export let creating=false;
let draft=structuredClone(profile),baseline,pending=false,error='',notice='',rampValid=true,targets=[],sharedTargets=[],targetBaseline='',targetsLoaded=false,leaveDialog,allowLeave=false,editorForm,flowMixOpen=false,tenancyCount=profile.mode==='tenancy'?profile.merchantCount:1500;
async function refreshTargets(){try{const [status,saved]=await Promise.all([api.faults(),api.faultTargets()]);targets=status.targets;if(!targetsLoaded){sharedTargets=saved;targetBaseline=JSON.stringify(saved);targetsLoaded=true;}}catch(e){error=e.message;}}
$: faultDirty=targetsLoaded&&JSON.stringify(sharedTargets)!==targetBaseline;
$: availableTargets=[...targets.filter(t=>!sharedTargets.some(s=>s.id===t.id)&&!JSON.parse(targetBaseline||'[]').some(s=>s.id===t.id)),...sharedTargets.map(t=>({...t,actions:t.adapter.startsWith('gcp-')?['failover']:['outage']}))];
if(creating){draft.name='New scenario';delete draft.id;delete draft.version;}baseline=creating?'':JSON.stringify(draft);
$: dirty=JSON.stringify(draft)!==baseline||faultDirty;
$: summary=(()=>{if(draft.loadShape!=='staged')return profileSummary(draft);try{const shape=loadShape({start_rps:Number(draft.startRps),stages:JSON.parse(draft.stagesJson)});return profileSummary({...draft,totalRps:shape.peak,durationSeconds:shape.duration});}catch{return 'Configure valid load stages';}})();
$: allocated=draft.scenarios.reduce((sum,flow)=>sum+Number(flow.weight||0),0);
$: if(allocated!==100)flowMixOpen=true;
$: merchantValid=draft.mode==='single'?Number(draft.merchantCount)===1:Number.isInteger(Number(draft.merchantCount))&&Number(draft.merchantCount)>=2&&Number(draft.merchantCount)<=1500;
$: canSave=draft.name.trim().length>0&&merchantValid&&allocated===100&&draft.scenarios.every(flow=>Number.isFinite(flow.weight)&&flow.weight>=0&&flow.weight<=100)&& (draft.loadShape!=='staged'||rampValid);
function setMerchantMode(mode){if(draft.mode==='tenancy')tenancyCount=draft.merchantCount;draft.mode=mode;draft.merchantCount=mode==='single'?1:Number(tenancyCount)||1500;}
beforeNavigate(navigation=>{if(allowLeave){allowLeave=false;return;}if(pending){navigation.cancel();return;}if(dirty&&navigation.to){navigation.cancel();leaveDialog.ask().then(leave=>{if(leave){allowLeave=true;if(navigation.to.url.origin===location.origin)goto(navigation.to.url,{replaceState:navigation.type==='popstate'});else location.href=navigation.to.url.href;}});}});
onMount(()=>{refreshTargets();window.addEventListener('console-connections-saved',refreshTargets);const unload=e=>{if(dirty){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',unload);return()=>{window.removeEventListener('beforeunload',unload);window.removeEventListener('console-connections-saved',refreshTargets);};});
async function save(){const invalid=editorForm?.querySelector(':invalid');if(invalid){for(let element=invalid.parentElement;element;element=element.parentElement)if(element.tagName==='DETAILS')element.open=true;invalid.focus();}if(!canSave||!targetsLoaded||!editorForm.reportValidity())return false;pending=true;error='';notice='';try{const result=await api.saveScenario({profile:draft,...(faultDirty?{targets:sharedTargets,expectedTargets:targetBaseline}:{})});draft=result.profile;sharedTargets=result.targets;targetBaseline=JSON.stringify(sharedTargets);baseline=JSON.stringify(draft);notice='Scenario saved';window.dispatchEvent(new Event('console-connections-saved'));return true;}catch(e){error=e.message;const area=editorForm.querySelector(e.message.match(/fault|vault|target|replica|controller/i)?'.fault-settings':'.basics');if(area?.tagName==='DETAILS')area.open=true;area?.scrollIntoView({block:'center',behavior:'smooth'});return false;}finally{pending=false;}}
async function submit(){if(await save())await goto(`/scenarios?tab=scenarios&view=edit&profile=${encodeURIComponent(draft.id)}`,{replaceState:true,keepFocus:true,noScroll:true});}
</script>
<div class="section-head"><div><a class="quiet" href="/scenarios"><Icon name="back"/> Back to scenarios</a><h1>{creating?'New scenario':draft.name}</h1><p>{summary}</p></div></div>
{#if error}<div class="message error" role="alert">{error}</div>{/if}
<UnsavedChanges bind:this={leaveDialog} save={save}/>
{#if creating}<p class="muted">Starting from: {profile.name}</p>{/if}
<form bind:this={editorForm} onsubmit={e=>{e.preventDefault();submit();}}>
<fieldset disabled={pending}>
<div class="basics" class:staged={draft.loadShape==='staged'} class:multiple={draft.mode==='tenancy'}><label>Scenario name<input required maxlength="100" bind:value={draft.name}/></label><label>Merchant setup<select value={draft.mode} onchange={event=>setMerchantMode(event.currentTarget.value)}><option value="single">Single merchant</option><option value="tenancy">Multiple merchants</option></select></label>{#if draft.mode==='tenancy'}<label>Number of merchants<input required type="number" min="2" max="1500" bind:value={draft.merchantCount}/></label>{/if}{#if draft.loadShape==='flat'}<label>Offered TPS<input required type="number" min="1" bind:value={draft.totalRps}/></label><label>Duration · seconds<input required type="number" min="1" bind:value={draft.durationSeconds}/></label>{/if}</div>
<div class="shape"><label>Load shape<select bind:value={draft.loadShape}><option value="flat">Constant TPS</option><option value="staged">Timeline · Hold, Ramp, Fault</option></select></label></div>
{#if draft.loadShape==='staged'}<RampEditor targets={availableTargets} bind:startRps={draft.startRps} bind:stagesJson={draft.stagesJson} bind:valid={rampValid}/>{/if}
<details class="editor-section flow-section" bind:open={flowMixOpen}><summary>Flow mix <span>{draft.scenarios.length} flows · {allocated}% allocated</span></summary><FlowMix bind:flows={draft.scenarios} disabled={pending}/></details>
<details class="advanced"><summary>Advanced <span>Acceptance thresholds</span></summary><div class="fields"><label>Minimum success ratio<input required type="number" min="0" max="1" step="0.01" bind:value={draft.acceptance.minimumSuccessRatio}/></label><label>Maximum HTTP errors · %<input required type="number" min="0" max="100" bind:value={draft.acceptance.maximumErrorPercent}/></label><label>Maximum client-side latency · ms<input required type="number" min="0" bind:value={draft.acceptance.maximumConfirmP99Ms}/></label><label>Maximum dropped flows<input required type="number" min="0" bind:value={draft.acceptance.maximumDropped}/></label></div></details>
</fieldset>
<details class="advanced fault-settings"><summary>Fault targets <span>{sharedTargets.length} configured · shared across scenarios</span></summary><p class="muted">Target changes save with this scenario. Existing runs keep their snapshots.</p>{#if targetsLoaded}<FaultSettings bind:targets={sharedTargets} baseline={targetBaseline}/>{:else}<p role="status">Loading targets…</p>{/if}</details>
<div class="flow-footer editor-save"><span class="save-status" role="status">{pending?'Saving…':dirty?(faultDirty?'Unsaved scenario / shared-target changes':'Unsaved changes'):notice || `Saved · version ${draft.version}`}</span><div class="actions"><button type="submit" disabled={pending||!dirty||!canSave||!targetsLoaded}>{#if !pending}<Icon name="check"/>{/if}{pending?'Saving…':'Save scenario'}</button></div></div>
{#if error}<p class="invalid" role="alert">{error}</p>{/if}{#if !canSave}<p class="invalid" role="status">{!draft.name.trim()?'Enter a scenario name.':!merchantValid?'Choose between 2 and 1,500 merchants.':allocated!==100?`Flow weights must total 100% (${allocated}% allocated).`:'Review the highlighted flow or timeline fields.'}</p>{/if}
</form>
<style>
.editor-save{position:sticky;bottom:0;z-index:20;padding:16px 0;background:#f6f8fbf2;border-top:1px solid var(--border);backdrop-filter:blur(8px);margin-top:24px}.editor-save .save-status{color:var(--muted)}fieldset{border:0;padding:0;margin:0;min-width:0}.section-head h1{margin-top:12px}.section-head a{display:inline-flex;align-items:center;gap:7px;font-size:12px}.basics{display:grid;grid-template-columns:1.5fr 1fr .7fr .7fr;gap:18px;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:20px}.basics.multiple{grid-template-columns:1.5fr 1fr .8fr .7fr .7fr}.basics.staged{grid-template-columns:1.5fr 1fr}.basics.staged.multiple{grid-template-columns:1.5fr 1fr .8fr}.shape{margin:20px 0 16px}.shape label{max-width:240px}.shape select{font-size:12px}.editor-section{margin:16px 0;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:16px 20px}.flow-section{width:min(100%,820px)}.editor-section summary>span,.advanced summary>span{margin-left:auto;font-size:11px;font-weight:400;color:var(--muted);text-align:right}.editor-section :global(.mix){border:0;padding:0;margin:14px 0 0;box-shadow:none}.editor-section :global(.mix .section-head h2),.editor-section :global(.mix .section-head p){display:none}.editor-section :global(.mix .section-head){justify-content:flex-start;margin-bottom:10px}.editor-section :global(.mix .section-head button){margin-left:0}.advanced{margin-top:14px}.fault-settings>p{max-width:620px;font-size:12px}@media(max-width:1000px){.basics,.basics.multiple{grid-template-columns:1fr 1fr}}@media(max-width:480px){.basics,.basics.staged,.basics.multiple,.basics.staged.multiple{grid-template-columns:1fr;padding:18px}.editor-save{padding:12px 0}.editor-save .save-status{font-size:11px}.editor-section summary,.advanced summary{flex-wrap:wrap}.editor-section summary>span,.advanced summary>span{margin-left:20px;text-align:left}}
</style>
